struct Resource{std::vector<uint8_t>m=std::vector<uint8_t>(1<<24);std::array<Event,8>events{};uint64_t status=0,busy=0;unsigned uartPolls=0;bool full=false;unsigned size=0,cost=0,lastTime=0;int previous=-1;void byte(uint32_t a,uint8_t v){m[a&0xffffff]=v;}void wide(uint32_t a,uint32_t v){for(unsigned n=0;n<4;++n)byte(a+n,uint8_t(v>>(24-8*n)));}void word(uint32_t a,uint16_t v){byte(a,v>>8);byte(a+1,v);}void see(bool write,uint32_t a,uint8_t v,unsigned dt){check(a<m.size()&&dt&&dt<=cost&&(!size||dt>=lastTime)&&size<events.size(),"Pure navigation callback address/order/time");events[size++]={write,a,v,dt};lastTime=dt;}uint8_t read(uint32_t a,unsigned dt){check(a<0xfff000||a>=0xfffc00,"Pure navigation observed a CPU continuation frame");auto v=a==0x400004||a==0x600004?uint8_t(status++<busy?0:255):m[a];if(full&&a==0xffed6f&&++uartPolls==4){m[a]=v=128;}see(false,a,v,dt);return v;}void write(uint32_t a,uint8_t v,unsigned dt){check(a<0xfff000||a>=0xfffc00,"Pure navigation wrote a CPU continuation frame");see(true,a,v,dt);m[a]=v;previous=history(a);}void phase(unsigned c){size=lastTime=0;cost=c;}};
